import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.CRfKVJQk.js";const p=JSON.parse('{"title":"Changelog","description":"Release history of react-native-liquid-glass-native, how to upgrade between versions, and known issues.","frontmatter":{"description":"Release history of react-native-liquid-glass-native, how to upgrade between versions, and known issues.","head":[["link",{"rel":"canonical","href":"https://sachinmeenasipl.github.io/react-native-glass-effect/reference/changelog"}],["meta",{"property":"og:url","content":"https://sachinmeenasipl.github.io/react-native-glass-effect/reference/changelog"}],["meta",{"property":"og:title","content":"Changelog · Liquid Glass for React Native"}],["meta",{"property":"og:description","content":"Release history of react-native-liquid-glass-native, how to upgrade between versions, and known issues."}],["meta",{"name":"twitter:title","content":"Changelog · Liquid Glass for React Native"}],["meta",{"name":"twitter:description","content":"Release history of react-native-liquid-glass-native, how to upgrade between versions, and known issues."}]]},"headers":[],"relativePath":"reference/changelog.md","filePath":"reference/changelog.md"}'),s={name:"reference/changelog.md"};function d(r,e,n,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="unreleased" tabindex="-1">Unreleased <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;Unreleased&quot;">​</a></h2><ul><li>New: Expo support documented and verified (Expo SDK 58 dev build; Expo Go uses the plain-view fallback)</li><li>New: web support (React, Vite, Next.js with SSR, Expo web). Web bundles resolve a web build through the <code>browser</code> and <code>node</code> export conditions, so native component specs are never bundled for the web</li><li>New: <code>react-native-web</code> is an optional peer dependency</li><li>Build: <code>npm run prepare</code> also writes <code>lib/web</code> (<code>scripts/build-web.js</code>)</li><li>Docs: new documentation site (VitePress, <code>website/</code>) with a separate installation guide per setup, a page per component and feature, recipes, and live web previews plus Android screenshots for every example</li><li>Examples: shared example scenes (<code>examples/shared/scenes</code>) used by the docs, the Vite gallery and the Expo app</li></ul><h2 id="_0-2-0" tabindex="-1">0.2.0 <a class="header-anchor" href="#_0-2-0" aria-label="Permalink to &quot;0.2.0&quot;">​</a></h2><ul><li>Fix (Android): glass never sampled its backdrop, so it drew a milky solid surface instead of blur and refraction</li><li>Fix (iOS): a <code>cornerRadius</code> above half the shortest side drew a broken shape</li><li>New: <code>&lt;LiquidGlass&gt;</code> Apple-style glass on both platforms, with <code>liquid</code> and <code>liquidClear</code> materials</li><li>New: <code>&lt;FrostedGlass&gt;</code> the same shader on Android and iOS</li><li>New: <code>iosRenderer=&quot;shader&quot;</code> Metal renderer for iOS; <code>&quot;system&quot;</code> stays the default</li><li>New: theme <code>iosRenderer</code> switches every glass on iOS at once, including buttons and cards</li><li>New: <code>&lt;GlassAdjuster&gt;</code> live tuning panel, plus <code>DEFAULT_GLASS_ADJUSTMENTS</code> and <code>stepAdjustment</code></li><li>Docs: list which props have no effect on iOS 26 system glass</li><li>Docs: demo videos for Android and iOS</li><li>Example: full-screen Types screen; tab selector no longer overlaps content</li></ul><h2 id="_0-1-0-—-first-public-version" tabindex="-1">0.1.0 — first public version <a class="header-anchor" href="#_0-1-0-—-first-public-version" aria-label="Permalink to &quot;0.1.0 — first public version&quot;">​</a></h2><ul><li><code>LiquidGlassView</code>, <code>GlassBackdrop</code>, <code>LiquidGlassButton</code>, <code>LiquidGlassCard</code></li><li>Materials: thin, regular, thick, clear; <code>GlassThemeProvider</code></li><li>Android: live RenderNode backdrop capture; GPU blur (12+); AGSL refraction, rim light, RGB split (13+); snapshot fallback (7–11)</li><li>Android: touch-follow light, press squish with spring, tilt lighting, animated prop transitions</li><li>Android: <code>quality=&quot;auto&quot;</code> (device class, RAM, battery saver, number of glass views)</li><li>iOS: <code>UIGlassEffect</code> on 26+, system materials on 15–25</li><li>Capabilities TurboModule + <code>useGlassCapabilities()</code></li><li>Safe JS fallbacks for Expo Go, web and tests</li><li>Shader: glossy rim line hugging the edge (tuned with the Skia preview)</li><li>Fix (Android): zero-size / hidden glass no longer triggers a redraw every frame</li><li>Fix (Android): glass flush with the screen edge no longer fades to see-through (sampling clipped to the backdrop, blur clamps)</li><li>Fix (Android 7–11): moving glass stays aligned (snapshot shifted per frame instead of throttled re-capture); press squish exact</li><li>Fix: disabled <code>LiquidGlassButton</code> no longer squishes/glows; iOS 26 button always has press feedback</li><li>Perf (Android): battery-saver state cached; RenderEffect chain reused when unchanged</li><li>Perf (Android): proximity filter, so only glass overlapping the changed view redraws (far-away spinners/Lottie are free)</li><li>Diagnostics: <code>getGlassStats()</code> / <code>resetGlassStats()</code>; live stats overlay on the example Stress screen</li><li>Tooling: <code>check:ios</code> (clang type-check against real iOS SDK + RN headers, iOS 26 branch included)</li><li>Tooling: <code>check:android</code> (compile Kotlin + JVM tests without an SDK), <code>preview:shader</code> (Skia render of the AGSL)</li></ul><h2 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h2><h3 id="from-0-2-to-the-next-release" tabindex="-1">From 0.2 to the next release <a class="header-anchor" href="#from-0-2-to-the-next-release" aria-label="Permalink to &quot;From 0.2 to the next release&quot;">​</a></h3><p>No breaking changes. The public API (<code>src/index.ts</code>) is unchanged.</p><ul><li>Web apps can now use the package directly. Add <code>react-native-web</code> and alias <code>react-native</code> to it. See <a href="/react-native-glass-effect/installation/web">Web</a>.</li><li>Expo dev builds need no config plugin. See <a href="/react-native-glass-effect/installation/expo">Expo</a>.</li></ul><h3 id="from-0-1-to-0-2" tabindex="-1">From 0.1 to 0.2 <a class="header-anchor" href="#from-0-1-to-0-2" aria-label="Permalink to &quot;From 0.1 to 0.2&quot;">​</a></h3><p>No breaking changes. 0.2 adds <code>LiquidGlass</code>, <code>FrostedGlass</code>, <code>GlassAdjuster</code>, the <code>liquid</code> and <code>liquidClear</code> materials, and the <code>iosRenderer</code> prop and theme setting.</p><p>The library follows semantic versioning. While it&#39;s below 1.0, a minor version may include breaking changes; they&#39;ll always be listed here with migration steps.</p><h2 id="known-issues" tabindex="-1">Known issues <a class="header-anchor" href="#known-issues" aria-label="Permalink to &quot;Known issues&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Issue</th><th>Where</th><th>Status</th></tr></thead><tbody><tr><td>Fabric logs &quot;Could not find generated setter&quot; for <code>LiquidGlassViewManager</code> and <code>GlassBackdropManager</code> at startup</td><td>Android (seen on Expo SDK 58, React Native 0.88)</td><td>Under investigation. Glass renders and props apply</td></tr><tr><td>No development warning when a prop is ignored on the current platform (for example <code>refraction</code> on the web)</td><td>All</td><td>Possible improvement</td></tr><tr><td>Native Android builds can fail on Windows when the project path is long</td><td>Windows</td><td>Workaround in <a href="/react-native-glass-effect/reference/troubleshooting#installation-and-builds">Troubleshooting</a></td></tr><tr><td>Blur is drawn incorrectly while glass fades (<code>opacity</code> below 1)</td><td>iOS</td><td>UIKit limitation. Fade the content instead</td></tr><tr><td>Content in a <code>SurfaceView</code> (some video and map views) can&#39;t be captured</td><td>Android</td><td>Use texture mode</td></tr><tr><td>Expo Go shows a plain fallback</td><td>Expo Go</td><td>By design: use a dev build</td></tr></tbody></table>',16)])])}const g=t(s,[["render",d]]);export{p as __pageData,g as default};
